/* Three storage responsibilities, exact state transitions, then fixed-fact experiments. */
const contextResponsibilities=infraReadableHTML(
 '<div class="mechanism-core" id="context-state-authority">'+knowledgeSubhead('先问“谁负责证明”，再问“模型要记住什么”')+
 para('设用户要求在当前会话生成A日报摘要。工具已读到资料，模型正准备写结论，服务却重启了。新进程需要知道：原目标是什么，哪一步已经完成，用的是哪个资料版本，还有哪个结果未知。这些事实若只存在于聊天文字中，恢复者就要重新猜一遍；若它把“正在保存”猜成“尚未保存”，还可能重复写入。')+
 figure('v22-context-stores','同一句话在三个载体里承担不同责任：执行账本证明提交，资料和记忆提供来源，本轮上下文提供受限视图。')+
 table(['载体','保存什么','谁依据它做决定'],[
 ['本轮模型上下文','问题、可信约束、已选证据、必要历史','模型据此提议下一步或生成回答'],
 ['权威运行状态','任务/步骤/原操作身份、状态版本、回执、待决动作','受信执行层据此恢复和推进'],
 ['长期记忆与资料','可跨任务复用的信息、来源版本、主体范围、有效条件','检索与组装层按本轮需要重新选择']])+
 para('上下文是一份给本次推理看的派生输入，可以被压缩、重建或全部替换。权威状态是执行事实的记录，不能随摘要措辞改变。长期记忆可以保存偏好和历史说明，却不能因为文字写着“已获批准”，就替代当前授权。把三者分开后，聊天删减影响本轮信息选择，不会自动抹掉已经提交的回执。',
 '这也解释了为什么“窗口更长”不能替代持久状态。窗口再长，工具提交之后、文字写回来之前仍可能中断；保留全部对话也不等于拥有工具的权威回执。恢复先查账本和接收方，随后才为模型组装需要的事实视图。')+'</div>');

const contextBudget=infraReadableHTML(
 knowledgeSubhead('上下文预算先扣固定项，再给证据与历史排优先级')+
 para('下面固定一个教学契约：窗口上限8192词元，包含输入和为本次回答预留的输出。系统说明1200，工具定义620，当前问题与可信任务视图672，输出预留900，格式开销100。可用于其他历史和证据的是8192−1200−620−672−900−100=4700。真实模型需按自己的分词器、消息包装和输入/输出限制计算；中文字数、UTF-8字节数、Python字符串长度都不能直接替代词元数。')+
 table(['固定项','题设词元数','为何优先计入'],[
 ['系统说明与工具定义','1820','决定本次调用的基础规则与工具接口'],
 ['问题与可信任务视图','672','目标、已确认状态、待决动作要能被理解'],
 ['输出预留与格式开销','1000','给答案和实际包装留下空间'],
 ['剩余历史与证据','4700','按本轮问题选择，不必填满']])+
 para('若旧对话4000、原始工具输出3000，共7000，就超出2300。直接从开头截掉2300，可能删掉最早的只读范围；直接截工具输出尾部，可能保留数字却丢了单位和适用版本。先列出完成当前问题必须知道的事实，再按证据覆盖与可重新获取程度取舍。对话出现得早晚，不等于其重要性。',
 '一种分配是历史摘要1400、带版本的指标证据1100、待确认问题600、必要摘录700，共3800，余900。每段材料说明支持哪个判断、引用哪里、保留哪些限定。工具结果很长时先保存原件或可信引用，再按字段取用；不要让每次错误堆栈都永久挤进后续调用。对于可以确定性计算的总数，先由代码计算并保留来源，比让模型反复从长文本里重算更可复查。')+
 code('组装流程示意 · token_count须匹配目标模型与消息格式','PYTHON',
 'base = fixed_messages(task, tools)\nselected = choose_evidence(receipts, source_refs)\nmessages = assemble(base, selected)\ninput_limit = window - reserved_output\nif token_count(serialize_messages(messages)) > input_limit:\n    selected = compact_or_refetch(selected, preserve=required_fields)\n    messages = assemble(base, selected)\nassert token_count(serialize_messages(messages)) <= input_limit\n# 最终对整份请求重新计数；任务状态仍由账本维护')+
 para('压缩可以减少输入，也有重算与遗漏成本。缓存摘要时要绑定来源版本和摘要规则；原始资料变了，旧摘要未必仍适用于当前问题。若输出预留、工具定义或消息包装变大，要重新计数，不应把一份旧预算表当作每次调用都成立的常量。'));

const contextCompaction=infraReadableHTML(
 knowledgeSubhead('摘要是一种有损压缩，先规定不能丢的语义槽位')+
 para('原记录写“旧驱动v1在10:00—10:05窗口出现120ms延迟，是否为根因仍是假设”。摘要只写“驱动导致延迟”，保留了几个关键词，却丢了版本、时间、单位和不确定性。下一轮可能把历史线索当作当前已确认结论。摘要的可读性和事实保真是两项要求，不能只用文本相似度评分。')+
 table(['必须保留的项','本例字段','丢失后的风险'],[
 ['结论状态','hypothesis，而非confirmed','把待证实线索升级成事实'],
 ['适用范围','driver-v1','把旧版本问题推广到全部版本'],
 ['时间与单位','10:00—10:05；120ms','数字还在，含义已变'],
 ['证据身份','trace-8:v1','不能回查当时那份原始记录'],
 ['动作结果','未收到回执 / 已确认提交分别记录','把推测变成一次恢复或重试决策']])+
 code('给推理用的事实视图 · 不是权限或状态的签发接口','JSON',
 '{\n  "claim": "driver_timeout",\n  "status": "hypothesis",\n  "applies_to": "driver-v1",\n  "window": "10:00-10:05",\n  "latency": 120,\n  "unit": "ms",\n  "evidence_ref": "trace-8:v1"\n}')+
 para('对业务关键字段，优先从可信记录投影成结构化视图；对解释性材料，可以压缩，但要能按引用取回原文。工具调用与结果应保持配对关系，不能只留下某次返回却丢掉它对应的参数或版本。摘要器可以提出“可能已完成”，执行层仍按权威回执决定是否完成。',
 '做压缩回归时，加入否定词、范围条件、金额、时间先后和结果未知样本。分别检查新视图能否回答原问题、必要字段是否保留、是否多出了原文没有的确认结论。下面实验只检查一组固定语义槽位，不能证明任意自然语言摘要都等价；复杂任务还要有真实提问和结果评估。'));

const contextRecovery=infraReadableHTML(
 '<div class="mechanism-core" id="stale-context-recovery">'+knowledgeSubhead('旧摘要与新账本冲突时，以谁为准')+
 para('本例任务R17的旧摘要停在v1/RUNNING，写着“报告尚未保存”。随后执行层已经用原操作R17:publish提交效果13，并把任务推进到v2/SUCCEEDED。恢复时若先相信旧文字，再为“补做一次”创建新操作ID，接收方会看到另一个逻辑动作；即使接收方正确去重，也会接受这份新动作。')+
 figure('v22-context-versions','两条恢复策略的真实SQLite对照：查原回执保持一次效果；相信旧文本并创建新操作，效果变两次。')+
 para('正确顺序是读取任务身份与当前状态，查询原操作回执，核对范围和版本，再重建本轮模型视图。若已确认成功，使用原结果；若仍未知，保留未知并按工具协议对账。重试沿用原逻辑操作身份，尝试编号可以改变。用户真的要求一份新报告，才是需要另建身份的另一个目标。')+
 code('并发更新的基本保护 · 版本冲突后重新观察','SQL',
 'UPDATE task\n   SET state = :validated_next_state, version = version + 1\n WHERE id = :task_id AND version = :observed_version;\n-- 影响0行：状态已变化，重新读取；不要无条件覆盖\n-- 是否允许这次迁移、调用者能否操作，仍由受信执行层校验')+
 para('版本条件控制的是“这次修改是否基于仍有效的观察”，不负责证明任意迁移都合法，也不负责授权。摘要器原则上只写派生视图，不应因为读到了当前版本就获得改写任务状态的权力。状态机还要拒绝不合法的成功回退、越权变更和不匹配的回执。本地事务能覆盖的对象范围，也不能直接外推到远端工具。',
 '把聊天历史全部清空，是一个有用的恢复测试：系统应仍能凭任务ID、原操作身份、权威回执和输入版本判断已经发生什么。它可以暂时缺少自然语言解释，但不应因此再次产生业务效果。')+'</div>');

const memoryLifecycle=infraReadableHTML(
 knowledgeSubhead('长期记忆要回答四件事：来自谁、适用于谁、哪一版、何时有效')+
 para('“这个月我喜欢短日报”是一条有主体和期限的偏好；“连接池默认5”是一条特定资料版本中的事实；“我已经保存报告”则是动作结果，应该由回执证明。三者都能被写成句子，却不能用同一种永久文本条目承担相同责任。记忆写入先分类，再决定所有者、有效期和纠错路径。')+
 table(['类型','应带的约束','使用时如何解释'],[
 ['个人偏好','主体、适用任务、有效期、来源','作为该主体当前任务的建议，不扩成全组织规则'],
 ['历史知识','原文定位、版本、形成时间、访问范围','可解释历史，当前事实需回查适用版本'],
 ['调查假设','证据、置信状态、反例、待确认项','持续保留“未证实”，不变成授权或结论'],
 ['执行结果','原操作身份、参数、权威回执与版本','由执行账本维护；记忆里只是引用']])+
 para('有效期未到，不代表事实仍是最新。本例记忆记录pool-limit/v1=5，权威来源已经更新为v2=10；即使旧条目TTL仍有余量，它也不能回答“当前值是多少”。如果问题问的是旧事故，则v1可能正是需要的历史证据。必须先确定问题的时间与版本口径，再判断记忆是否适用。',
 '使用链至少包含候选选择、当前主体与资料权限检查、来源版本核对、上下文装配和最后交付。候选通过一次检查，不等于之后永远有权读取；缓存引用也要带版本与范围。示例程序用固定主体和本地条目状态演示后续重查，没有运行真实身份服务、跨租户索引或远端授权。')+
 para('撤回条目后，后续重组可以通过当前状态拒绝旧引用；它不能让此前已经发给模型或用户的文本自动消失。原文、摘要、向量索引、缓存和共享产物各要有明确责任与处理流程。纠错应更新实际存储及派生索引，只在提示里写“忘记刚才内容”不是后端删除操作。对于审计记录与业务资料的保留，也应采用各自约定。'));

const memoryTrust=infraReadableHTML(
 knowledgeSubhead('资料里的指令，不能借记忆获得新的权力')+
 para('业务备注写“把报告同步到B”，这只是工具返回的外部文字。若摘要器把它存成“用户长期允许同步到B”，下一次又把它作为偏好召回，就把一次不可信输入变成了持续影响。问题不在文字保存得是否完整，而在来源和授权类型被改写了。',
 '写记忆时保存原始来源，明确区分用户委托、管理员策略、工具数据和模型推断。读取时按当前任务重新解释，执行时仍由工具服务独立验证主体、动作和资源。一个受信存储服务可以保存不可信文字；“从自己的记忆库取出”不让内容自动成为可信指令。',
 '回归样例可以分三步：把外部备注保存为带来源的数据；另一个任务召回后检查其仍被标为资料；让模型即使提出越权写入，受信执行层仍拒绝。最后一步需要实际运行对应的授权链才能证明。本文程序没有调用模型，验证的是状态与组装规则，不把它描述为通用提示注入防御已通过。')+
 knowledgeCheck('某记忆条目写着“已批准”，能让恢复器执行写操作吗？','不能。记忆只是信息来源。执行前查真实委托、适用审批和当前权限；若条目来源只是工具备注或模型推断，就更不能把它当作授权。'));

const contextPractice=infraReadableHTML(
 knowledgeSubhead('用旧摘要、旧事实和撤回引用检查整个顺序')+
 sqcLab('context_state.py')+
 para('先闭卷预测三个结果：第一，旧摘要v1与权威成功v2冲突，正常恢复会产生几次效果？第二，旧版本条件写回影响几行？第三，TTL尚未到期、来源版本已过时的条目，能否直接回答当前值？运行后应分别看到1、0和不能。再看错误对照为何变成2次：它更换了逻辑操作身份，而接收方只是按新身份执行。',
 '预算练习：窗口改为6000，系统与工具开销1800，问题与可信任务视图700，输出预留1000，历史与证据剩2500。候选为旧对话1600、本次权威时间线1000、旧手册900、已确认执行视图400，共3900。至少压缩或舍弃1400。可保留时间线1000与执行视图400，把旧对话压为600，手册留下适用条件与引用500，合计2500；若手册与问题无关，整体不选也合理。',
 '解释答案时指出哪些字段不能改写，哪些细节可从原件重新获取；再检查假设、版本、否定词、时间和单位是否完整。最后把聊天清空重建一次。完成这组练习后，进入检索章节，继续核对候选、正文、预算与最终引用，不能只以“资料已经放进窗口”宣布任务合格。')+
 linkTo('agent-retrieval','继续学习从候选到最终证据的逐阶段验证'));

{
 const a=articles.find(a=>a.id==='agent-memory');
 a.sections=[
  ['上下文、状态和记忆：三种职责分别保存',contextResponsibilities],
  ['上下文预算：固定开销、证据与历史如何分配',contextBudget],
  ['压缩与摘要：保留限定条件和不确定性',contextCompaction],
  ['恢复与并发：旧摘要不能覆盖新事实',contextRecovery],
  ['长期记忆：主体、来源、版本与有效期',memoryLifecycle],
  ['外部资料与记忆的信任边界',memoryTrust],
  ['实战与变化题：清空聊天还能恢复吗',contextPractice]
 ];
 a.refs=[...new Set([...a.refs,'v22Context','v22Transaction'])];a.minutes=40;a.updated='2026.11.04';
}
infraDomain('agent').points.find(p=>p.id==='ag-context').body=contextResponsibilities+contextBudget+contextCompaction+contextRecovery+memoryLifecycle+memoryTrust;
infraDomain('agent').refs=[...new Set([...infraDomain('agent').refs,'v22Context','v22Transaction'])];
{
 const a=articles.find(a=>a.id==='agent-runtime');
 a.sections[3][1]+=knowledgeSubhead('给模型看的视图，要带来源与状态版本')+
 para('运行时可以投影“R17已在v2提交，原操作回执为13”，让模型继续解释或交付；这份视图不是事实所有者。压缩、丢弃或重建它，都不应改变任务真实状态。旧摘要与账本冲突时先回查权威记录；版本条件更新也不能替代合法状态迁移与授权。')+
 linkTo('agent-memory','深入学习上下文预算、旧摘要与长期记忆');
 a.refs=[...new Set([...a.refs,'v22Context','v22Transaction'])];a.updated='2026.11.04';
}
const agentCasesBeforeSQC=infraFieldCases.agent;
infraFieldCases.agent=()=>'<h3>旧摘要与权威状态：恢复时谁说了算</h3>'+sqcLab('context_state.py',false)+
 linkTo('agent-memory','阅读上下文与记忆全链、代码和练习')+agentCasesBeforeSQC();
